#!/usr/bin/env python3
import sys


def get_num_of_paty(n):
    return 2**(n+1)-1

def get_num_of_lay(n):
    return 2**(n+2)-3

def solve(N: int, X: int):

    ans = 0
    now_level = N + 1
    for i in range(N+1):
        now_level -= 1
        pivot = (get_num_of_lay(now_level)+1)/2
        if X > pivot:#get a half party
            ans += get_num_of_paty(now_level-1)+1
            X -= pivot
        elif X == pivot:
            ans += get_num_of_paty(now_level-1)+1
            break
        else:
            X -= 1

    print(ans)


# Generated by 1.1.6 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    X = int(next(tokens))  # type: int
    solve(N, X)

if __name__ == '__main__':
    main()
